// data/costume-spine.json schema check (generated by tools/fetch-prts-spine.mjs from PRTS).
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

describe('data/costume-spine.json', () => {
  const data = JSON.parse(readFileSync(join(ROOT, 'data', 'costume-spine.json'), 'utf8'));

  it('exists and covers a meaningful share of the costume gallery', () => {
    assert.equal(typeof data.chars, 'object');
    const charIds = Object.keys(data.chars);
    assert.ok(charIds.length >= 80, `expected >=80 charIds, got ${charIds.length}`);
  });

  it('every entry is a well-formed remote spine entry (skel/atlas/textures/anims)', () => {
    const okUrl = (u) => typeof u === 'string' && u.startsWith('https://torappu.prts.wiki/assets/char_spine/');
    let skins = 0;
    for (const [charId, skinsByName] of Object.entries(data.chars)) {
      assert.match(charId, /^char_\d+_[a-z0-9_]+$/, charId);
      for (const [skinName, e] of Object.entries(skinsByName)) {
        skins++;
        assert.ok(skinName.length > 0, 'skin name');
        for (const side of ['front', 'back']) {
          const entry = e[side];
          if (!entry) { if (side === 'front') assert.fail(`${charId}/${skinName}: missing front`); continue; }
          assert.ok(okUrl(entry.skel) && entry.skel.endsWith('.skel'), `${charId}/${skinName}/${side} skel`);
          assert.ok(okUrl(entry.atlas) && entry.atlas.endsWith('.atlas'), `${charId}/${skinName}/${side} atlas`);
          assert.ok(Array.isArray(entry.textures) && entry.textures.length >= 1, `${charId}/${skinName}/${side} textures`);
          assert.equal(typeof entry.pma, 'boolean');
          assert.ok(entry.anims && typeof entry.anims === 'object', `${charId}/${skinName}/${side} anims`);
          assert.match(entry.spineVersion, /^[234]\.\d+\.\d+$/);
        }
      }
    }
    assert.ok(skins >= 150, `expected >=150 skins with spine, got ${skins}`);
  });

  it('anims resolve to skin-skeleton animation names (idle/die present for every front)', () => {
    for (const skinsByName of Object.values(data.chars)) {
      for (const { front } of Object.values(skinsByName)) {
        if (!front) continue;
        // every role key present; idle must resolve (else the model would stand frozen)
        assert.ok('idle' in front.anims, 'idle role present');
        assert.equal(typeof front.anims.idle, 'string');
        assert.equal(typeof front.anims.die, 'string');
        for (const [role, v] of Object.entries(front.anims)) {
          if (role === 'skills') continue;
          if (v === null || v === undefined) continue;
          if (typeof v === 'string') assert.ok(v.length > 0, `role ${role}`);
          else if (typeof v === 'object') {
            for (const [k, vv] of Object.entries(v)) {
              if (k === 'index' || k === 'via' || vv === null) continue;
              if (typeof vv === 'string') assert.ok(vv.length > 0);
            }
          }
        }
      }
    }
  });
});
